// Packages: AWSSDK.SecretsManager, Amazon.SecretsManager
using Amazon.SecretsManager;
using Amazon.SecretsManager.Model;
using Microsoft.Extensions.Caching.Memory;

public class SecretService
{
    private readonly ISecretsManagerService _secretsClient;
    private readonly IMemoryCache _cache;
    private readonly MemoryCacheEntryOptions _cacheOptions;

    public SecretService(ISecretsManagerService secretsClient, IMemoryCache cache)
    {
        _secretsClient = secretsClient;
        _cache = cache;
        // Cache secrets for 5 minutes to reduce network calls and avoid throttling
        _cacheOptions = new MemoryCacheEntryOptions { AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5) };
    }

    public async Task<string> GetSecretAsync(string secretName, CancellationToken cancellationToken = default)
    {
        try
        {
            // Check cache first
            if (_cache.TryGetValue(secretName, out string cachedSecret))
            {
                Console.WriteLine($"Returning cached secret: {secretName}");
                return cachedSecret;
            }

            var request = new GetSecretValueRequest
            {
                SecretId = secretName
            };

            GetSecretValueResponse response = await _secretsClient.GetSecretValueAsync(request, cancellationToken);
            string secretValue = response.SecretString;

            // Cache the secret for future requests
            _cache.Set(secretName, secretValue, _cacheOptions);
            Console.WriteLine($"Retrieved secret from Secrets Manager: {secretName}");

            return secretValue;
        }
        catch (AmazonSecretsManagerException ex)
        {
            Console.WriteLine($"Secrets Manager error for {secretName}: {ex.Message}");
            throw;
        }
    }
}

