// Packages: AWSSDK.SecretsManager, Amazon.SecretsManager
using Amazon.SecretsManager;

var builder = WebApplication.CreateBuilder(args);

try
{
    var secretsClient = new SecretsManagerClient(RegionEndpoint.USEast1);
    builder.Configuration.AddSecretsManager(config =>
    {
        config.SecretManager = secretsClient;
        config.MapPath = (name, json) =>
        {
            if (name == "aspnet/connectionstrings/default")
                return ConfigurationPath.Path("ConnectionStrings:Default");
            return name;
        };
        // Optional: filter which secrets are loaded
        config.KeyGenerator = (name, json) => name.Replace("/", ":");
    });
}
catch (AmazonSecretsManagerException ex)
{
    Console.WriteLine($"Failed to load secrets: {ex.Message}");
    throw;
}

var connectionString = builder.Configuration.GetConnectionString("Default");
Console.WriteLine($"Connection string loaded: {connectionString}");

var app = builder.Build();
app.MapGet("/", () => "Secrets Manager configured");
app.Run();

// Expected output: "Connection string loaded: Server=tcp:aspnet-db.xxx.us-east-1.rds.amazonaws.com,1433;..."
